Here are several ways to find duplicates:

```python
# Method 1: Find all duplicates
def find_duplicates_v1(lst):
    seen = set()
    duplicates = set()
    for item in lst:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)
    return list(duplicates)

# Method 2: Using Counter
from collections import Counter
def find_duplicates_v2(lst):
    counts = Counter(lst)
    return [item for item, count in counts.items() if count > 1]

# Method 3: Find duplicates with their count
def find_duplicates_with_count(lst):
    counts = Counter(lst)
    return {item: count for item, count in counts.items() if count > 1}

# Method 4: Find only the first duplicate
def find_first_duplicate(lst):
    seen = set()
    for item in lst:
        if item in seen:
            return item
        seen.add(item)
    return None

# Examples
numbers = [1, 2, 3, 2, 4, 5, 3, 6]
print(find_duplicates_v1(numbers))  # [2, 3]
print(find_duplicates_with_count(numbers))  # {2: 2, 3: 2}
```
